function lf_status($raw):string{$s=str_replace([' ','-'],'_',strtolower(trim((string)$raw)));if(in_array($s,['reported','pending','open'],true))return'reported';if(in_array($s,['driver_notified','driver_contacted','awaiting_driver'],true))return'driver_contacted';if(in_array($s,['driver_responded','searching','check_later'],true))return'searching';if(in_array($s,['item_found','found'],true))return'item_found';if(in_array($s,['return_arranged','return_scheduled','return_pending'],true))return'return_arranged';if($s==='returned')return'returned';if(in_array($s,['not_found','item_not_found'],true))return'not_found';if(in_array($s,['cancelled','canceled'],true))return'cancelled';if(in_array($s,['closed','resolved'],true))return'closed';return'reported';}
