$in=lf_input();$action=strtolower(trim((string)($in['action']??'list')));$admin=$_SESSION['admin_auth']??[];
try{
if($action==='list'){$ctx=['rides'=>[],'passengers'=>[],'drivers'=>[]];foreach(admin_list_collection('rides',1000)as$x){foreach(array_unique(array_filter([(string)($x['uid']??''),lf_text($x,['rideCode','rideId','bookingId'])]))as$k)$ctx['rides'][$k]=$x;}foreach(admin_list_collection('passengers',1000)as$x)$ctx['passengers'][(string)($x['uid']??'')]=$x;foreach(admin_list_collection('drivers',1000)as$x)$ctx['drivers'][(string)($x['uid']??'')]=$x;$rows=[];$seen=[];foreach(admin_list_collection(LF_COLLECTION,200)as$x){$id=(string)($x['uid']??'');if($id==='')continue;$r=lf_normalize($id,$x,$ctx);$key=strtolower($r['case_id']);if(isset($seen[$key]))continue;$seen[$key]=1;$rows[]=$r;}usort($rows,static fn($a,$b)=>strcmp($b['created_at'],$a['created_at']));lf_json(['ok'=>true,'cases'=>$rows]);}
$id=trim((string)($in['caseId']??$in['id']??''));if($id==='')lf_json(['ok'=>false,'message'=>'Case is required.'],422);$case=wow_doc_data(LF_COLLECTION,$id);if(!$case)lf_json(['ok'=>false,'message'=>'Lost & Found case was not found.'],404);
if($action==='detail'){$ctx=['rides'=>[],'passengers'=>[],'drivers'=>[]];$rideId=lf_text($case,['rideId']);if($rideId!=='')$ctx['rides'][$rideId]=wow_doc_data('rides',$rideId)?:[];$pid=lf_text($case,['passengerId']);$did=lf_text($case,['driverId']);if($pid!=='')$ctx['passengers'][$pid]=wow_doc_data('passengers',$pid)?:[];if($did!=='')$ctx['drivers'][$did]=wow_doc_data('drivers',$did)?:[];$timeline=[];foreach(admin_list_collection(LF_COLLECTION."/$id/timeline",200)as$x)$timeline[]=['event'=>lf_text($x,['description','eventType']),'status'=>lf_text($x,['newStatus']),'admin'=>lf_text($x,['adminName']),'notes'=>lf_text($x,['notes']),'created_at'=>lf_time($x['createdAt']??'')];usort($timeline,static fn($a,$b)=>strcmp($a['created_at'],$b['created_at']));lf_json(['ok'=>true,'case'=>lf_normalize($id,$case,$ctx),'timeline'=>$timeline]);}
if($action==='note'){$notes=trim((string)($in['notes']??''));if($notes==='')lf_json(['ok'=>false,'message'=>'Enter an internal note.'],422);wow_set_doc(LF_COLLECTION,$id,['adminNotes'=>$notes,'updatedAt'=>wow_now()],true);lf_activity($id,'admin_note',lf_status($case['status']??''),lf_status($case['status']??''),$admin,$notes);lf_json(['ok'=>true]);}
