if($action==='arrange_return'){$method=trim((string)($in['returnMethod']??''));$when=trim((string)($in['returnScheduledAt']??''));$location=trim((string)($in['returnLocation']??''));$notes=trim((string)($in['notes']??''));if($method===''||$when===''||$location==='')lf_json(['ok'=>false,'message'=>'Return method, date/time and location are required.'],422);if(strtotime($when)===false||strtotime($when)<=time())lf_json(['ok'=>false,'message'=>'Choose a future return date and time.'],422);$prev=lf_status($case['status']??'');if($prev!=='item_found')lf_json(['ok'=>false,'message'=>'Return can be arranged only after the item is found.'],422);wow_set_doc(LF_COLLECTION,$id,['status'=>'Return Arranged','returnMethod'=>$method,'returnScheduledAt'=>$when,'returnLocation'=>$location,'returnNotes'=>$notes,'returnStatus'=>'scheduled','updatedAt'=>wow_now()],true);lf_activity($id,'return_arranged',$prev,'return_arranged',$admin,$notes);lf_notify($case,$id,'Lost item return arranged','A return arrangement has been created for your lost item.',[lf_text($case,['passengerId']),lf_text($case,['driverId'])],$admin);lf_json(['ok'=>true]);}
if($action==='status'){$next=lf_status($in['status']??'');$prev=lf_status($case['status']??'');$valid=['reported'=>['driver_contacted','searching','cancelled'],'driver_contacted'=>['searching','item_found','not_found','cancelled'],'searching'=>['item_found','not_found','cancelled'],'item_found'=>['return_arranged'],'return_arranged'=>['returned'],'returned'=>['closed'],'not_found'=>['closed'],'cancelled'=>['closed'],'closed'=>['reported']];if(!in_array($next,$valid[$prev]??[],true))lf_json(['ok'=>false,'message'=>'This status transition is not allowed.'],422);$notes=trim((string)($in['notes']??''));if(in_array($next,['not_found','cancelled','closed','reported'],true)&&$notes==='')lf_json(['ok'=>false,'message'=>'A reason is required for this status change.'],422);$updates=['status'=>ucwords(str_replace('_',' ',$next)),'updatedAt'=>wow_now()];if($next==='driver_contacted')$updates+=['driverContactedAt'=>wow_now(),'driverContactedBy'=>(string)($admin['uid']??'')];if($next==='item_found')$updates['foundAt']=wow_now();if($next==='returned')$updates+=['returnedAt'=>wow_now(),'returnedBy'=>(string)($admin['uid']??'')];if($next==='closed')$updates+=['closedAt'=>wow_now(),'closedBy'=>(string)($admin['uid']??''),'closureReason'=>$notes];if($prev==='closed'&&$next==='reported')$updates+=['reopenedAt'=>wow_now(),'reopenedBy'=>(string)($admin['uid']??''),'reopenReason'=>$notes];wow_set_doc(LF_COLLECTION,$id,$updates,true);lf_activity($id,'status_changed',$prev,$next,$admin,$notes);$messages=['driver_contacted'=>'The driver has been contacted regarding your lost item.','item_found'=>'Good news! The driver has confirmed that your item was found.','return_arranged'=>'A return arrangement has been created for your lost item.','returned'=>'Your lost item has been marked as returned.','closed'=>'Your Lost & Found case has been closed.','not_found'=>'The item could not be found.','cancelled'=>'Your Lost & Found case was cancelled.','searching'=>'The driver is searching for your lost i